    #[test]
    fn execute_ixor_xors_bits() {
        let r = execute(
            &[
                (0, Instruction::Bipush(5_i8)),
                (2, Instruction::Bipush(3_i8)),
                (4, Instruction::Ixor),
                (5, Instruction::Ireturn),
            ],
            &[],
            vec![],
            4,
            0,
        )
        .unwrap()
        .unwrap();
        assert_eq!(r, Slot::Int(6)); // 5 ^ 3 = 6
    }

